    dest=a.output/'target';dest.mkdir();shutil.copy2(folder/'case.xml',dest/'case.xml');grid,sides,weights,count=n.inventory(c)
    req=replay(initial,native['state'],0.,grid,grid_sides=sides,export_test_basis=True,export_neutral_composite_reference=True,export_ct10_momentum=True,ct10_export_points=False)
